 *     public init(_ val: Int) { self.val = val; self.left = nil; self.right = nil; }
 *     public init(_ val: Int, _ left: TreeNode?, _ right: TreeNode?) {
 *         self.val = val
 *         self.left = left
 *         self.right = right
 *     }
 * }
 */
class Solution {
    func diameterOfBinaryTree(_ root: TreeNode?) -> Int {
        guard let root = root else { return 0 }

        let leftHeight = maxHeight(root.left)
        let rightHeight = maxHeight(root.right)
        let diameter = leftHeight + rightHeight
        let sub = max(diameterOfBinaryTree(root.left), diameterOfBinaryTree(root.right))

        return max(diameter, sub)
    }

    private func maxHeight(_ root: TreeNode?) -> Int {
        guard let root = root else { return 0 }
        return 1 + max(maxHeight(root.left), maxHeight(root.right))
    }
}

impl Solution {
    pub fn diameter_of_binary_tree(root: Option<Rc<RefCell<TreeNode>>>) -> i32 {
        fn max_height(root: &Option<Rc<RefCell<TreeNode>>>) -> i32 {
            match root {
                None => 0,
                Some(node) => {
                    let node = node.borrow();
                    1 + max_height(&node.left).max(max_height(&node.right))
                }
            }
        }

        match root {
            None => 0,
            Some(ref node) => {
                let n = node.borrow();
                let left_height = max_height(&n.left);
                let right_height = max_height(&n.right);
                let diameter = left_height + right_height;
                let sub = Self::diameter_of_binary_tree(n.left.clone())
                    .max(Self::diameter_of_binary_tree(n.right.clone()));
                diameter.max(sub)
            }
        }
    }
}

