        mp[null] = Pair(0, 0)

        while (stack.isNotEmpty()) {
            val node = stack.last()

            when {
                node.left != null && !mp.containsKey(node.left) -> {
                    stack.addLast(node.left)
                }
                node.right != null && !mp.containsKey(node.right) -> {
                    stack.addLast(node.right)
